from pathlib import Path
p=Path('/mnt/data/ppp_revise/index.html')
s=p.read_text()
s=s.replace('<button class="tab-btn" data-tab="calendar">🗓️ Trainingskalender</button>','')
# Replace calendar form and registered list with a panda prompt above calendar, and a single deletion control below
old='''root.innerHTML=`<div class="panel calendar-panel"><div class="eyebrow">Jouw consistentie</div><h2 class="selected-title">🗓️ Trainingskalender</h2><p class="muted">Klik op een dag om te registreren of je training aan te passen. Je kunt ook vergeten trainingen van eerdere dagen toevoegen.</p><div class="calendar-head"><button class="secondary small" id="calendarPrev">← Vorige</button><h3 style="margin:0;text-transform:capitalize">${esc(monthName)}</h3><button class="secondary small" id="calendarNext">Volgende →</button></div><div class="calendar-grid">${weekdays.map(d=>`<div class="calendar-weekday">${d}</div>`).join('')}${cells}</div><div class="calendar-form"><div class="wide"><label for="trainingDate">Datum</label><input id="trainingDate" type="date" value="${localISODate()}" required></div><div class="wide"><label for="trainingDescription">🐼 Wat heb/ga je vandaag trainen?</label><input id="trainingDescription" maxlength="120" placeholder="Bijv. Borst en tricep, rug en bicep…"></div><div class="wide" style="display:flex;gap:8px;flex-wrap:wrap"><button class="primary" id="saveTrainingDay">Training opslaan</button><button class="secondary" id="clearTrainingDay">Dag leegmaken</button></div><div class="wide muted" id="calendarStatus" aria-live="polite">Selecteer een datum op de kalender om die dag te bekijken of te wijzigen.</div></div><h3 class="section-title">Jouw geregistreerde trainingen</h3>${entries.length?entries.map(x=>`<div class="calendar-entry"><strong>${esc(formatDate(x.date))}</strong><div>${esc(x.training)}</div><button class="secondary small" data-edit-training="${esc(x.date)}">Aanpassen</button><button class="secondary small" data-delete-training="${esc(x.date)}">Verwijderen</button></div>`).join(''):'<div class="empty-card">Je hebt nog geen trainingen via deze kalender geregistreerd. 🐼</div>'}</div>`;'''
new='''const motivator=activePanda();
 root.innerHTML=`<div class="panel calendar-panel"><div class="calendar-prompt"><img src="./pandas/motivator/${motivator.id}.jpg" alt="${esc(motivator.name)}" onerror="this.style.display='none'"><div class="calendar-prompt-content"><div class="calendar-speech">Wat heb je vandaag getraint?</div><label for="trainingDescription">Vertel het aan ${esc(motivator.name)}:</label><input id="trainingDescription" maxlength="120" placeholder="Bijv. Borst en tricep, rug en bicep…"></div></div><div class="eyebrow">Jouw consistentie</div><h2 class="selected-title">🗓️ Trainingskalender</h2><p class="muted">Klik op een dag om de datum te selecteren. Je kunt ook een training van een eerdere dag toevoegen.</p><div class="calendar-head"><button class="secondary small" id="calendarPrev">← Vorige</button><h3 style="margin:0;text-transform:capitalize">${esc(monthName)}</h3><button class="secondary small" id="calendarNext">Volgende →</button></div><div class="calendar-grid">${weekdays.map(d=>`<div class="calendar-weekday">${d}</div>`).join('')}${cells}</div><div class="calendar-form"><div class="wide"><label for="trainingDate">Geselecteerde datum</label><input id="trainingDate" type="date" value="${localISODate()}" required></div><div class="wide" style="display:flex;gap:8px;flex-wrap:wrap"><button class="primary" id="saveTrainingDay">Training opslaan</button></div><div class="wide muted" id="calendarStatus" aria-live="polite">Selecteer een datum op de kalender en vul hierboven je training in.</div><div class="wide"><button class="secondary" id="deleteSelectedTraining">Verwijder training van geselecteerde dag</button></div></div></div>`;'''
if old not in s: raise SystemExit('calendar markup not found')
s=s.replace(old,new)
s=s.replace(" const dateInput=$(\"trainingDate\"),desc=$(\"trainingDescription\"),status=$(\"calendarStatus\");", " const dateInput=$(\"trainingDate\"),desc=$(\"trainingDescription\"),status=$(\"calendarStatus\");")
# Update loadDate to sync prompt input (same desc is now above calendar, so unchanged)
old2=" $('clearTrainingDay').onclick=()=>{const date=dateInput.value;if(!date)return;data.trainingDays=data.trainingDays.filter(x=>x.date!==date);persist();renderCalendar();loadDate(date);status.textContent='De kalenderregistratie voor deze dag is verwijderd. Eerder opgeslagen oefeningstrainingen blijven behouden.'};\n root.querySelectorAll('[data-edit-training]').forEach(b=>b.onclick=()=>{loadDate(b.dataset.editTraining);desc.focus();root.scrollIntoView({behavior:'smooth',block:'start'})});\n root.querySelectorAll('[data-delete-training]').forEach(b=>b.onclick=()=>{const date=b.dataset.deleteTraining;data.trainingDays=data.trainingDays.filter(x=>x.date!==date);persist();renderCalendar()});"
new2=" $('deleteSelectedTraining').onclick=()=>{const date=dateInput.value;if(!date){status.textContent='Selecteer eerst een datum.';return}data.trainingDays=data.trainingDays.filter(x=>x.date!==date);persist();renderCalendar();const refreshedDate=$(\"trainingDate\"),refreshedStatus=$(\"calendarStatus\"),refreshedDesc=$(\"trainingDescription\");refreshedDate.value=date;refreshedDesc.value='';refreshedStatus.textContent='De kalendertraining voor '+formatDate(date)+' is verwijderd. Andere opgeslagen oefeningstrainingen blijven behouden.'};"
if old2 not in s: raise SystemExit('old handlers not found')
s=s.replace(old2,new2)
# add styling for panda + speech prompt
needle='.calendar-panel{padding:16px}'
addition='.calendar-prompt{display:flex;align-items:center;gap:14px;margin:0 0 20px;padding:12px;background:linear-gradient(110deg,#4a1c43,#2b172f);border:1px solid #85436d;border-radius:16px}.calendar-prompt img{width:100px;height:100px;object-fit:contain;flex-shrink:0;border-radius:14px}.calendar-prompt-content{flex:1;min-width:0}.calendar-speech{position:relative;display:inline-block;background:#fff0f9;color:#461438;padding:12px 14px;border-radius:14px;font-weight:800;margin-bottom:9px}.calendar-speech:before{content:"";position:absolute;left:-6px;top:18px;width:12px;height:12px;background:#fff0f9;transform:rotate(45deg)}.calendar-prompt label{display:block;font-size:12px;color:var(--muted);margin-bottom:5px}.calendar-prompt input{width:100%}@media(max-width:440px){.calendar-prompt{gap:9px;padding:9px}.calendar-prompt img{width:76px;height:76px}.calendar-speech{padding:10px;font-size:13px}}'
s=s.replace(needle,addition+needle)
# keep motivator banner as sole entrypoint; calendar view only opens from it
p.write_text(s)
